const anthropicText = (r) => {
  if (!r || !Array.isArray(r.content)) {
    const m = (r && r.error && (r.error.message || r.error.type || r.error.description)) || 'no response';
    return { ok: false, error: String(m).slice(0, 200) };
  }
  if (r.stop_reason === 'max_tokens') return { ok: false, error: 'answer truncated (max_tokens)' };
  if (r.stop_reason === 'refusal') return { ok: false, error: 'model declined the request' };
  if (r.stop_reason === 'pause_turn') return { ok: false, error: 'web search did not finish (pause_turn)' };
  const text = r.content.filter(b => b && b.type === 'text' && b.text).map(b => b.text).join('').trim();
  if (!text) return { ok: false, error: 'empty answer' };
  return { ok: true, text };
};
const stripFences = (t) => String(t).replace(/^\s*```[a-z]*\s*/i, '').replace(/\s*```\s*$/, '');
const r = $input.first().json;
const mk = (o) => { const obs = o; return [{ json: { probe: obs } }]; };
const fail = (m) => mk({ ok: false, reason: String(m).slice(0, 300) });
const res = anthropicText(r);
if (!res.ok) return fail(res.error);
const text = stripFences(res.text);
const start = text.indexOf('{');
if (start < 0) return fail('no JSON object in model output');
let depth = 0, end = -1;
for (let i = start; i < text.length; i++) {
  if (text[i] === '{') depth++;
  else if (text[i] === '}') { depth--; if (depth === 0) { end = i; break; } }
}
if (end < 0) return fail('unbalanced JSON in model output');
let o;
try { o = JSON.parse(text.slice(start, end + 1)); } catch (e) { return fail('unparseable model output'); }
if (o.ok !== true) return mk({ ok: false, reason: String(o.reason || 'model reported cannot_determine').slice(0, 300) });
if (typeof o.value !== 'number' || !isFinite(o.value)) return fail('value is not a finite number');
return mk({ ok: true, value: o.value, unit: String(o.unit || ''), as_of: String(o.as_of || ''), source_url: String(o.source_url || '') });

